mapper.insert:
INSERT INTO ocr_binding (
    version_id, ocr_task_id, status, engine_version, detection_preview_url,
    detection_preview_content_type, detection_preview_size, detection_preview_sha256,
    detection_preview_width, detection_preview_height, field_count
) VALUES (
    #{versionId}, #{ocrTaskId}, #{status}, #{engineVersion}, #{detectionPreviewUrl},
    #{detectionPreviewContentType}, #{detectionPreviewSize}, #{detectionPreviewSha256},
    #{detectionPreviewWidth}, #{detectionPreviewHeight}, #{fieldCount}
)

mapper.select:
SELECT b.id AS binding_id, b.version_id, e.id AS employee_id, b.ocr_task_id, b.error_message, b.updated_at FROM ocr_binding b JOIN archive_version v ON v.id = b.version_id JOIN archive_document d ON d.id = v.document_id AND d.status = 'ACTIVE' JOIN archive_record ar ON ar.id = d.archive_record_id AND ar.status = 'ACTIVE' JOIN employee e ON e.id = ar.employee_id AND e.status = 'ACTIVE' WHERE b.status = 'FAILED'
AND 1 = 1 AND e.department_id = #{departmentId} AND e.id = #{employeeId} AND 1 = 0
ORDER BY b.updated_at DESC, b.id DESC LIMIT #{limit}

mapper.insert:
INSERT INTO ocr_field_confirmation (
    binding_id, field_code, original_value, confirmed_value, confidence, operator_id, reason
) VALUES (
    #{bindingId}, #{fieldCode}, #{originalValue}, #{confirmedValue}, #{confidence}, #{operatorId}, #{reason}
)
